-- firewatch.lua
-- Wallpaper-derived colorscheme generated by DankMaterialShell matugen.
-- Do not edit manually; change the template in ~/.config/matugen/templates/firewatch.lua instead.

vim.cmd("hi clear")
if vim.fn.exists("syntax_on") == 1 then
  vim.cmd("syntax reset")
end

vim.o.termguicolors = true
vim.o.background = "dark"
vim.g.colors_name = "firewatch"

local c = {
  bg          = "{{colors.background.default.hex}}",
  bg_dark     = "{{colors.surface_container_lowest.default.hex}}",
  bg_high     = "{{colors.surface_container_high.default.hex}}",
  bg_highest  = "{{colors.surface_container_highest.default.hex}}",
  fg          = "{{colors.on_background.default.hex}}",
  fg_muted    = "{{colors.on_surface_variant.default.hex}}",
  comment     = "{{colors.outline.default.hex}}",
  primary     = "{{colors.primary.default.hex}}",
  primary_deep= "{{colors.primary_container.default.hex}}",
  on_primary  = "{{colors.on_primary.default.hex}}",
  secondary   = "{{colors.secondary.default.hex}}",
  tertiary    = "{{colors.tertiary.default.hex}}",
  red         = "{{colors.error.default.hex}}",
  green       = "{{dank16.color2.default.hex}}",
  yellow      = "{{dank16.color3.default.hex}}",
  blue        = "{{dank16.color4.default.hex}}",
  magenta     = "{{dank16.color13.default.hex}}",
  cyan        = "{{dank16.color12.default.hex}}",
  orange      = "{{colors.secondary.default.hex}}",
  none        = "NONE",
}

local function hi(group, opts)
  vim.api.nvim_set_hl(0, group, opts)
end

-- Editor chrome
hi("Normal",       { fg = c.fg, bg = c.bg })
hi("NormalNC",     { fg = c.fg_muted, bg = c.bg })
hi("NormalFloat",  { fg = c.fg, bg = c.bg_high })
hi("FloatBorder",  { fg = c.outline or c.comment, bg = c.bg_high })
hi("FloatTitle",   { fg = c.primary, bg = c.bg_high, bold = true })
hi("Cursor",       { fg = c.bg, bg = c.primary })
hi("CursorLine",   { bg = c.bg_high })
hi("CursorLineNr", { fg = c.primary, bold = true })
hi("LineNr",       { fg = c.comment })
hi("SignColumn",   { bg = c.bg })
hi("ColorColumn",  { bg = c.bg_high })
hi("VertSplit",    { fg = c.bg_highest, bg = c.bg })
hi("WinSeparator", { fg = c.bg_highest, bg = c.bg })
hi("Visual",       { bg = c.primary_deep, fg = c.fg })
hi("VisualNOS",    { bg = c.primary_deep })
hi("Search",       { fg = c.on_primary, bg = c.tertiary, bold = true })
hi("IncSearch",    { fg = c.on_primary, bg = c.primary, bold = true })
hi("CurSearch",    { fg = c.on_primary, bg = c.primary, bold = true })
hi("MatchParen",   { fg = c.tertiary, bold = true, underline = true })
hi("Pmenu",        { fg = c.fg_muted, bg = c.bg_high })
hi("PmenuSel",     { fg = c.on_primary, bg = c.primary, bold = true })
hi("PmenuSbar",    { bg = c.bg_highest })
hi("PmenuThumb",   { bg = c.comment })
hi("StatusLine",   { fg = c.fg, bg = c.bg_highest })
hi("StatusLineNC", { fg = c.comment, bg = c.bg_high })
hi("TabLine",      { fg = c.comment, bg = c.bg_high })
hi("TabLineSel",   { fg = c.on_primary, bg = c.primary, bold = true })
hi("TabLineFill",  { bg = c.bg_high })
hi("Folded",       { fg = c.comment, bg = c.bg_high })
hi("FoldColumn",   { fg = c.comment, bg = c.bg })
hi("NonText",      { fg = c.bg_highest })
hi("Whitespace",   { fg = c.bg_highest })
hi("SpecialKey",   { fg = c.comment })
hi("Directory",    { fg = c.primary, bold = true })
hi("Title",        { fg = c.primary, bold = true })
hi("ErrorMsg",     { fg = c.red, bold = true })
hi("WarningMsg",   { fg = c.yellow })
hi("MoreMsg",      { fg = c.green })
hi("Question",     { fg = c.green })
hi("ModeMsg",      { fg = c.fg, bold = true })
hi("QuickFixLine", { bg = c.bg_highest })
hi("WildMenu",     { fg = c.on_primary, bg = c.primary })
hi("DiffAdd",      { fg = c.green, bg = c.bg_high })
hi("DiffChange",   { fg = c.yellow, bg = c.bg_high })
hi("DiffDelete",   { fg = c.red, bg = c.bg_high })
hi("DiffText",     { fg = c.on_primary, bg = c.tertiary })
hi("Added",        { fg = c.green })
hi("Changed",      { fg = c.yellow })
hi("Removed",      { fg = c.red })

-- Syntax
hi("Comment",      { fg = c.comment, italic = true })
hi("Constant",     { fg = c.primary })
hi("String",       { fg = c.green })
hi("Character",    { fg = c.green })
hi("Number",       { fg = c.tertiary })
hi("Boolean",      { fg = c.tertiary })
hi("Float",        { fg = c.tertiary })
hi("Identifier",   { fg = c.fg })
hi("Function",     { fg = c.primary, bold = true })
hi("Statement",    { fg = c.magenta })
hi("Conditional",  { fg = c.magenta })
hi("Repeat",       { fg = c.magenta })
hi("Label",        { fg = c.magenta })
hi("Operator",     { fg = c.secondary })
hi("Keyword",      { fg = c.magenta, italic = true })
hi("Exception",    { fg = c.red })
hi("PreProc",      { fg = c.secondary })
hi("Include",      { fg = c.secondary })
hi("Define",       { fg = c.secondary })
hi("Macro",        { fg = c.secondary })
hi("PreCondit",    { fg = c.secondary })
hi("Type",         { fg = c.yellow })
hi("StorageClass", { fg = c.yellow })
hi("Structure",    { fg = c.yellow })
hi("Typedef",      { fg = c.yellow })
hi("Special",      { fg = c.cyan })
hi("SpecialChar",  { fg = c.cyan })
hi("Tag",          { fg = c.primary })
hi("Delimiter",    { fg = c.fg_muted })
hi("SpecialComment", { fg = c.comment, bold = true })
hi("Debug",        { fg = c.orange })
hi("Underlined",   { underline = true })
hi("Ignore",       { fg = c.comment })
hi("Error",        { fg = c.red, bold = true })
hi("Todo",         { fg = c.on_primary, bg = c.yellow, bold = true })

-- Diagnostics / LSP
hi("DiagnosticError", { fg = c.red })
hi("DiagnosticWarn",  { fg = c.yellow })
hi("DiagnosticInfo",  { fg = c.cyan })
hi("DiagnosticHint",  { fg = c.comment })
hi("DiagnosticUnderlineError", { undercurl = true, sp = c.red })
hi("DiagnosticUnderlineWarn",  { undercurl = true, sp = c.yellow })
hi("DiagnosticUnderlineInfo",  { undercurl = true, sp = c.cyan })
hi("DiagnosticUnderlineHint",  { undercurl = true, sp = c.comment })
hi("LspReferenceText",  { bg = c.bg_highest })
hi("LspReferenceRead",  { bg = c.bg_highest })
hi("LspReferenceWrite", { bg = c.bg_highest })

